/// A list of [`LIST_LEN`] items with operations that change one item at a time.
@MainActor @Observable
public final class BigList: KeelStore {
    public private(set) var items: [Item] = []
    /// Computed by the core; read-only.
    public private(set) var count: UInt32 = 0

    private init(adopting handle: KeelHandle, core: KeelCore) {
        super.init(core: core, handle: handle)
        core.observe(handle, signal: Observe.allSignals, on: true)
    }

    /// A list of [`LIST_LEN`] items numbered from 1.
    public convenience init(ctx: KeelCore = .shared) throws {
        let handle = try ctx.construct(
            type: KeelIds.Objects.BigList.typeId,
            method: KeelIds.Objects.BigList.new,
            args: []
        )
        self.init(adopting: handle, core: ctx)
    }

    /// Inserts a new row with `label` so that it ends at `index` (`index == len` appends), and
    /// returns its identity. One keyed `Insert`.
    /// - Throws: ``ListError``.
    public func insertAt(index: UInt32, label: String) throws(ListError) -> UInt32 {
        var w = KeelWriter()
        index.keelEncode(&w)
        label.keelEncode(&w)
        do {
            let body = try self.core.callSync(
                .objectMethod(handle: self.handle, methodId: KeelIds.Objects.BigList.insertAt),
                method: KeelIds.Objects.BigList.insertAt,
                args: w.finish()
            )
            return try UInt32.keelDecoded(from: body)
        } catch {
            guard let typed = ListError.keelFromReply(error) else { keelUnexpected(error) }
            throw typed
        }
    }

    /// Moves the row at `from` so that it ends at `to`. One keyed `Move`.
    /// - Throws: ``ListError``.
    public func moveItem(from: UInt32, to: UInt32) throws(ListError) {
        var w = KeelWriter()
        from.keelEncode(&w)
        to.keelEncode(&w)
        do {
            _ = try self.core.callSync(
                .objectMethod(handle: self.handle, methodId: KeelIds.Objects.BigList.moveItem),
                method: KeelIds.Objects.BigList.moveItem,
                args: w.finish()
            )
        } catch {
            guard let typed = ListError.keelFromReply(error) else { keelUnexpected(error) }
            throw typed
        }
    }

    /// Removes the row at `index`. One keyed `Remove`.
    /// - Throws: ``ListError``.
    public func removeAt(index: UInt32) throws(ListError) {
        var w = KeelWriter()
        index.keelEncode(&w)
        do {
            _ = try self.core.callSync(
                .objectMethod(handle: self.handle, methodId: KeelIds.Objects.BigList.removeAt),
                method: KeelIds.Objects.BigList.removeAt,
                args: w.finish()
            )
        } catch {
            guard let typed = ListError.keelFromReply(error) else { keelUnexpected(error) }
            throw typed
        }
    }

    /// Replaces the list with a fresh one of [`LIST_LEN`] items. The platform receives the keyed
    /// patch that turns the old list into the new one (a full value if they have little in
    /// common).
    public func reset() {
        do {
            _ = try self.core.callSync(
                .objectMethod(handle: self.handle, methodId: KeelIds.Objects.BigList.reset),
                method: KeelIds.Objects.BigList.reset,
                args: []
            )
        } catch {
            keelUnexpected(error)
        }
    }

    /// Changes the label of the row at `index` and bumps its version. One keyed `Update`.
    /// - Throws: ``ListError``.
    public func updateAt(index: UInt32, label: String) throws(ListError) {
        var w = KeelWriter()
        index.keelEncode(&w)
        label.keelEncode(&w)
        do {
            _ = try self.core.callSync(
                .objectMethod(handle: self.handle, methodId: KeelIds.Objects.BigList.updateAt),
                method: KeelIds.Objects.BigList.updateAt,
                args: w.finish()
            )
        } catch {
            guard let typed = ListError.keelFromReply(error) else { keelUnexpected(error) }
            throw typed
        }
    }

    public override func apply(signal: UInt32, op: ChangeOp, reader: inout KeelReader) {
        do {
            switch signal {
            case 0:
                switch op {
                case .fullValue:
                    self.items = try [Item].keelDecode(&reader)
                    try reader.finish()
                case .keyedPatch:
                    let ops: [PatchOp<Item>] = try decodePatch(&reader)
                    try reader.finish()
                    try applyPatch(ops, to: &self.items)
                case .lazyListInvalidated:
                    break
                }
            case 1:
                switch op {
                case .fullValue:
                    self.count = try UInt32.keelDecode(&reader)
                    try reader.finish()
                case .keyedPatch:
                    break
                case .lazyListInvalidated:
                    break
                }
            default:
                break
            }
        } catch is PatchError {
            // The mirror diverged from the core: re-observe to receive a full value.
            self.core.observe(self.handle, signal: signal, on: false)
            self.core.observe(self.handle, signal: signal, on: true)
        } catch {
            assertionFailure("Keel: undecodable change for signal \(signal) of BigList: \(error)")
        }
    }
}

/// A counter with a change tally and a computed parity.
@MainActor @Observable
public final class Counter: KeelStore {
    public private(set) var count: Int32 = 0
    public private(set) var changes: UInt32 = 0
    /// Computed by the core; read-only.
    public private(set) var parity: Parity = .even

