        let handle = try ctx.construct(
            type: KeelIds.Objects.Counter.typeId,
            method: KeelIds.Objects.Counter.new,
            args: []
        )
        self.init(adopting: handle, core: ctx)
    }

    /// Adds `amount` (which may be negative) and counts the change: one transaction, so one
    /// change-set for `count`, `changes` and `parity` together. The count saturates instead of
    /// overflowing.
    public func add(amount: Int32) {
        var w = KeelWriter()
        amount.keelEncode(&w)
        do {
            _ = try self.core.callSync(
                .objectMethod(handle: self.handle, methodId: KeelIds.Objects.Counter.add),
                method: KeelIds.Objects.Counter.add,
                args: w.finish()
            )
        } catch {
            keelUnexpected(error)
        }
    }

    /// Subtracts one.
    public func decrement() {
        do {
            _ = try self.core.callSync(
                .objectMethod(handle: self.handle, methodId: KeelIds.Objects.Counter.decrement),
                method: KeelIds.Objects.Counter.decrement,
                args: []
            )
        } catch {
            keelUnexpected(error)
        }
    }

    /// Adds one.
    public func increment() {
        do {
            _ = try self.core.callSync(
                .objectMethod(handle: self.handle, methodId: KeelIds.Objects.Counter.increment),
                method: KeelIds.Objects.Counter.increment,
                args: []
            )
        } catch {
            keelUnexpected(error)
        }
    }

    /// Sets the count back to zero and forgets the changes, in one transaction.
    public func reset() {
        do {
            _ = try self.core.callSync(
                .objectMethod(handle: self.handle, methodId: KeelIds.Objects.Counter.reset),
                method: KeelIds.Objects.Counter.reset,
                args: []
            )
        } catch {
            keelUnexpected(error)
        }
    }

    public override func apply(signal: UInt32, op: ChangeOp, reader: inout KeelReader) {
        do {
            switch signal {
            case 0:
                switch op {
                case .fullValue:
                    self.count = try Int32.keelDecode(&reader)
                    try reader.finish()
                case .keyedPatch:
                    break
                case .lazyListInvalidated:
                    break
                }
            case 1:
                switch op {
                case .fullValue:
                    self.changes = try UInt32.keelDecode(&reader)
                    try reader.finish()
                case .keyedPatch:
                    break
                case .lazyListInvalidated:
                    break
                }
            case 2:
                switch op {
                case .fullValue:
                    self.parity = try Parity.keelDecode(&reader)
                    try reader.finish()
                case .keyedPatch:
                    break
                case .lazyListInvalidated:
                    break
                }
            default:
                break
            }
        } catch is PatchError {
            // The mirror diverged from the core: re-observe to receive a full value.
            self.core.observe(self.handle, signal: signal, on: false)
            self.core.observe(self.handle, signal: signal, on: true)
        } catch {
            assertionFailure("Keel: undecodable change for signal \(signal) of Counter: \(error)")
        }
    }
}

/// The to-do list: what the UI observes (`todos`, `filter`, `visible`, `remaining`) and calls.
@MainActor @Observable
public final class Todos: KeelStore {
    public private(set) var todos: [Todo] = []
    public private(set) var filter: Filter = .all
    /// Computed by the core; read-only.
    public private(set) var visible: [Todo] = []
    /// Computed by the core; read-only.
    public private(set) var remaining: UInt32 = 0

    private init(adopting handle: KeelHandle, core: KeelCore) {
        super.init(core: core, handle: handle)
        core.observe(handle, signal: Observe.allSignals, on: true)
    }

    /// An empty list showing every item.
    public convenience init(ctx: KeelCore = .shared) throws {
        let handle = try ctx.construct(
            type: KeelIds.Objects.Todos.typeId,
            method: KeelIds.Objects.Todos.new,
            args: []
        )
        self.init(adopting: handle, core: ctx)
    }

    /// Adds an item at the end of the list.
    /// - Throws: ``TodoError``.
    public func add(title: String) async throws(TodoError) -> Todo {
        var w = KeelWriter()
        title.keelEncode(&w)
        do {
            let body = try await self.core.call(
                .objectMethod(handle: self.handle, methodId: KeelIds.Objects.Todos.add),
                method: KeelIds.Objects.Todos.add,
                args: w.finish()
            )
            return try Todo.keelDecoded(from: body)
        } catch {
            guard let typed = TodoError.keelFromReply(error) else { keelUnexpected(error) }
            throw typed
        }
    }

    /// Removes every finished item.
    public func clearDone() {
        do {
            _ = try self.core.callSync(
                .objectMethod(handle: self.handle, methodId: KeelIds.Objects.Todos.clearDone),
                method: KeelIds.Objects.Todos.clearDone,
                args: []
            )
        } catch {
            keelUnexpected(error)
        }
    }

    /// Removes the item with `id`; unknown ids are ignored.
    public func remove(id: UUID) {
        var w = KeelWriter()
        id.keelEncode(&w)
        do {
            _ = try self.core.callSync(
                .objectMethod(handle: self.handle, methodId: KeelIds.Objects.Todos.remove),
                method: KeelIds.Objects.Todos.remove,
                args: w.finish()
            )
        } catch {
            keelUnexpected(error)
        }
    }

    /// Chooses which items `visible` holds.
    public func setFilter(_ filter: Filter) {
        var w = KeelWriter()
        filter.keelEncode(&w)
        do {
            _ = try self.core.callSync(
                .objectMethod(handle: self.handle, methodId: KeelIds.Objects.Todos.setFilter),
                method: KeelIds.Objects.Todos.setFilter,
                args: w.finish()
            )
        } catch {
            keelUnexpected(error)
        }
    }

    /// Flips the `done` flag of the item with `id`; unknown ids are ignored.
    public func toggle(id: UUID) {
        var w = KeelWriter()
        id.keelEncode(&w)
        do {
            _ = try self.core.callSync(
                .objectMethod(handle: self.handle, methodId: KeelIds.Objects.Todos.toggle),
                method: KeelIds.Objects.Todos.toggle,
                args: w.finish()
            )
        } catch {
            keelUnexpected(error)
        }
    }

    public override func apply(signal: UInt32, op: ChangeOp, reader: inout KeelReader) {
        do {
            switch signal {
            case 0:
                switch op {
                case .fullValue:
                    self.todos = try [Todo].keelDecode(&reader)
                    try reader.finish()
                case .keyedPatch:
                    let ops: [PatchOp<Todo>] = try decodePatch(&reader)
                    try reader.finish()
                    try applyPatch(ops, to: &self.todos)
                case .lazyListInvalidated:
                    break
                }
            case 1:
                switch op {
                case .fullValue:
                    self.filter = try Filter.keelDecode(&reader)
                    try reader.finish()
                case .keyedPatch:
                    break
                case .lazyListInvalidated:
                    break
                }
            case 2:
                switch op {
                case .fullValue:
                    self.visible = try [Todo].keelDecode(&reader)
                    try reader.finish()
                case .keyedPatch:
                    break
                case .lazyListInvalidated:
                    break
                }
            case 3:
                switch op {
                case .fullValue:
                    self.remaining = try UInt32.keelDecode(&reader)
                    try reader.finish()
                case .keyedPatch:
                    break
                case .lazyListInvalidated:
                    break
                }
            default:
                break
            }
        } catch is PatchError {
            // The mirror diverged from the core: re-observe to receive a full value.
            self.core.observe(self.handle, signal: signal, on: false)
            self.core.observe(self.handle, signal: signal, on: true)
        } catch {
            assertionFailure("Keel: undecodable change for signal \(signal) of Todos: \(error)")
        }
    }
}
